```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_partition",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' src, service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50, MAX(duration)/1e6 mx FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name LIKE 'POST%' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, COUNT(*), quantile_cont(duration,0.5)/1e6, MAX(duration)/1e6 FROM normal_traces WHERE service_name='ts-seat-service' AND span_name LIKE 'POST%' GROUP BY ALL ORDER BY 3,1",
          "claim": "Seat service receives POST /api/v1/seatservice/seats 128 times normally but zero times in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_span_kind, span_name, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, MAX(duration)/1e6 max_ms, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST' AND attr_span_kind='Client' AND duration > 100000000000 GROUP BY ALL",
          "claim": "Preserve's outgoing POST calls to seat hang about 130 s and end in error, with 12 such failures."
        },
        {
          "kind": "log",
          "sql": "SELECT level, message, COUNT(*) n FROM abnormal_logs WHERE service_name='ts-preserve-service' AND message LIKE '%ts-seat-service%' GROUP BY 1,2",
          "claim": "Preserve logs SEVERE 'Connection timed out' I/O errors on POST to http://ts-seat-service:8080/api/v1/seatservice/seats."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, MAX(duration)/1e6 max_ms, SUM(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST /api/v1/preserveservice/preserve' GROUP BY ALL",
          "claim": "Preserve's server spans take about 130 s p50 and all 12 fail, versus 127 normal requests at about 296 ms."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, COUNT(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, MAX(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "User-facing dashboard calls to the preserve endpoint take about 20 s p50 in the abnormal period, versus about 297 ms normally."
        }
      ]
    }
  ]
}
